The preparation stage to have a superposition of all balanced assignments of $n$ qubits will use the 
amplitude amplification technique shown in \cite{Younes2013} since it achieves the highest known probability of success 
using fixed operators and it can be summarized as follows, prepare a superposition of $2^n$ states by initializing 
$n$ qubits to state $\left| {0} \right\rangle$ and apply $H^{\otimes n}$ on the $n$ qubits
\begin{equation}
\begin{array}{l}
 \left| {\Psi _0 } \right\rangle  = \left( {H^{ \otimes n}} \right) \left| 0 \right\rangle ^{ \otimes n}  \\ 
 \,\,\,\,\,\,\,\,\,\,\,\,\, = \frac{1}{{\sqrt N }}\sum\limits_{j = 0}^{N - 1} {\left| j \right\rangle },  \\ 
 \end{array}
\end{equation}

\noindent
where $H$ is the Hadamard gate, and $N=2^n$. 
Assume that the system $\left| {\Psi _0 } \right\rangle$ is re-written as follows,

\begin{equation} \begin{array}{l}
\left|\Psi_0\right\rangle =  \frac{1}{{\sqrt N }} \sum\limits_{\scriptstyle j = 0, \hfill \atop 
  \scriptstyle j \in X_T  \hfill}^{N - 1} {\left| j \right\rangle} 
  + \frac{1}{{\sqrt N }} \sum\limits_{\scriptstyle j = 0, \hfill \atop 
  \scriptstyle j \in X_F  \hfill}^{N - 1} {\left| j \right\rangle},\\
\end{array} 
\end{equation}

\noindent
where $X_T$ is the set of all balanced assignments of $n$ bits and $X_F$ is the set of all 
unbalanced assignments. Let $M=\left( {\begin{array}{*{20}c}
   n  \\
   {{\textstyle{n \over 2}}}  \\
\end{array}} \right)$ be the number of balanced assignments among the $2^n$ possible assignments, 
$\sin (\theta ) = \sqrt {{M \mathord{\left/ {\vphantom {M N}} \right.\kern-\nulldelimiterspace} N}}$ 
and $0 < \theta  \le \pi /2$, then the system can be re-written as follows,



\begin{equation}
\left|\Psi_0\right\rangle  = \sin (\theta )\left| {\psi _1 } \right\rangle  + \cos (\theta )\left| {\psi _0 } \right\rangle,
\end{equation}

\noindent
where $\left| {\psi _1 } \right\rangle= \left| {\tau  } \right\rangle$ represents the balanced assignments subspace and 
$\left| {\psi _0 } \right\rangle$ represents the unbalanced assignments subspace. 



Let $D=WR_0 \left( \phi  \right)W^\dag  R_\tau  \left( \phi  \right)$, 
$R_0 \left( \phi  \right) = I - (1 - e^{i\phi } )\left| 0 \right\rangle \left\langle 0 \right|$, 
$R_\tau  \left( \phi  \right) = I - (1 - e^{i\phi } )\left| \tau  \right\rangle \left\langle \tau  \right|$, 
where $W=H^{\otimes n}$ is the Walsh-Hadamard transform \cite{hoyer00}. 
Iterate the operator $D$ on $\left|\Psi_0\right\rangle$ for $q$ times to get,


\begin{equation}
\left| {\Psi _1 } \right\rangle  = D^{q}\left| {\Psi_0 } \right\rangle  = a_q \left| {\psi _1 } \right\rangle  + b_q \left| {\psi _0 } \right\rangle ,
\end{equation}

\noindent
such that, 
\begin{equation} a_q  = \sin (\theta )\left( {e^{iq\phi } U_q \left( y \right) + e^{i(q - 1)\phi } U_{q - 1} \left( y \right)} \right), 
\end{equation}

\begin{equation}
b_q =  \cos (\theta )e^{i(q - 1)\phi } \left( {U_q \left( y \right) + U_{q - 1} \left( y \right)} \right),
\end{equation} 

\noindent  
where $y=cos(\delta)$, $\cos \left( \delta  \right) = 2\sin ^2 (\theta )\sin ^2 ({\textstyle{\phi  \over 2}}) - 1$,
 $0<\theta\le \pi/2$, and $U_q$ is the Chebyshev polynomial of the second kind \cite{ChebPoly} defined as follows, 

\begin{equation}
 U_q \left( y \right) = \frac{{\sin \left( {\left( {q + 1} \right)\delta } \right)}}{{\sin \left( \delta  \right)}}.
\end{equation}

Setting $\phi=6.02193\approx1.9168\pi$, $M=\left( {\begin{array}{*{20}c}
   n  \\
   {{\textstyle{n \over 2}}}  \\
\end{array}} \right)$, $N=2^n$ and, $q = \left\lfloor {{\textstyle{\phi  \over {\sin (\theta)}}}} \right\rfloor$, then
$\left| {a_q } \right|^2  \ge 0.9975$ \cite{Younes2013}. The upper bound for the required number of iterations $q$ to reach the maximum probability of success is,

\begin{equation} q = \left\lfloor {{\textstyle{\phi  \over {\sin (\theta)}}}} \right\rfloor \le 1.9168\pi\sqrt {\frac{N}{M}},
\end{equation}
\noindent
and using Stirling's approximation,

\begin{equation}
n! \approx \sqrt {2\pi n} \left( {\frac{n}{e}} \right)^n,
\end{equation}
\noindent
then, the upper bound for required number of iterations $q$ to prepare the superposition of all balanced assignments is,

\begin{equation}
q \approx 1.9168\sqrt[4]{{\frac{{\pi ^5 }}{{2 }}n}} = O\left( \sqrt[4]{n} \right).
\end{equation}


It is required to preserve the states in $\left| {\psi _1 } \right\rangle$ for further processing in the next stage. 
This can be done by adding an auxiliary qubit $\left| {ax_1 } \right\rangle$ initialized to state 
$\left| {0} \right\rangle$ and have the states of the balanced assignments entangled with 
$\left| {ax_1 } \right\rangle = \left| {1} \right\rangle$, so that, 
the correctness of the items in the 
superposition can be verified by applying measurement on $\left| {ax_1 } \right\rangle$ without having to examine 
