The $m^{th}$ partial negation operator is the $m^{th}$ root of $\sigma _X$ and 
can be calculated using diagonalization as follows, 

\begin{equation}
 V=\sqrt[m]{\sigma _X} = \frac{1}{2}\left[ {\begin{array}{*{20}c}
   {1 + t} & {1 - t}  \\
   {1 - t} & {1 + t}  \\
\end{array}} \right],
\end{equation}

\noindent
where $t={\sqrt[m]{{ - 1}}}$, and applying $V$ for $d$ times on a qubit is equivalent to the operator,

\begin{equation}
 V^d  = \frac{1}{2}\left[ {\begin{array}{*{20}c}
   {1 + t^d } & {1 - t^d }  \\
   {1 - t^d } & {1 + t^d }  \\
\end{array}} \right],
\end{equation}

\noindent
such that if $d=m$, then $V^m=\sigma _X$.

For the sake of simplicity and to avoid duplication, 
the operator $Q$ will denote either the operator $MAX$ or the operator $MIN$, $d$ will denote either $d_1$ or $d_0$, 
$\left| {z_s } \right\rangle$ will denote either $\left| {z_{max} } \right\rangle$ or $\left| {z_{min} } \right\rangle$, 
and $d_s$ will denote either $d_{max1}$ or $d_{max0}$, so, 

\begin{equation}
Q\left( {\left| {c_0 c_1 ...c_{m - 1} } \right\rangle  \otimes \left| 0 \right\rangle } \right) = \left| {c_0 c_1 ...c_{m - 1} } \right\rangle  \otimes \left( {\frac{{1 + t^{d} }}{2}\left| 0 \right\rangle  + \frac{{1 - t^{d} }}{2}\left| 1 \right\rangle } \right),
\end{equation}

\noindent
and the probabilities of finding the auxiliary qubit $\left|ax_2 \right\rangle$ in state 
${\left| 0 \right\rangle }$ or ${\left| 1 \right\rangle }$ when measured is respectively as follows,

\begin{equation}
\begin{array}{l}
 Pr{(ax_2  = 0)}  = \left| {\frac{{1 + t^d }}{2}} \right|^2  = \cos ^2 \left( {\frac{{d\pi }}{{2m}}} \right), \\ 
 Pr{(ax_2  = 1)}  = \left| {\frac{{1 - t^d }}{2}} \right|^2  = \sin ^2 \left( {\frac{{d\pi }}{{2m}}} \right). \\ 
 \end{array}
\end{equation}

To find the state ${\left| z_s \right\rangle }$ in $\left| {\psi _m } \right\rangle$, 
the proposed algorithm is as follows, as shown in Figure \ref{mmfig}:

\begin{itemize}
\item[1-] Let $\left| {\psi _r } \right\rangle = \left| {\psi _m } \right\rangle$.
\item[2-]  Repeat the following steps for $r$ times,
\begin{itemize}
\item[i-] Apply the operator $Q$ on $\left| {\psi _r } \right\rangle$.
\item[ii-] Measure $\left| ax_2 \right\rangle$, 
if $\left|ax_2 \right\rangle=\left|1 \right\rangle$, 
then let the system post-measurement is $\left| {\psi _r } \right\rangle$, apply $\sigma_X$ on $\left| ax_2 \right\rangle$ 
to reset to $\left| 0 \right\rangle$ for the next iteration and then go to Step (i), otherwise restart the stage and go to Step (1).
\end{itemize}
\item[3-] Measure the first $m$ qubits in $\left| {\psi _r } \right\rangle$ to read $\left| z_s \right\rangle$.
\end{itemize}

Assuming that the algorithm finds $\left|ax_2 \right\rangle=\left|1 \right\rangle$ for $r$ times 
in a row, then the probability of finding $\left|ax_2 \right\rangle=\left|1 \right\rangle$ after Step (2-i) in 
the $1^{st}$ iteration, i.e. $r=1$ is given by,

\begin{equation}
Pr^{(1)}{(ax_2  = 1)}  = \alpha ^2 \sum\limits_{k = 0}^{M - 1} {\sin ^2 \left( {\frac{{d_k \pi }}{{2m}}} \right)}. \end{equation}

The probability of finding $\left|\psi_r \right\rangle=\left|z_s \right\rangle$ after Step (2-i) in 
the $1^{st}$ iteration, i.e. $r=1$ is given by,

\begin{equation}
Pr^{(1)}{(\psi_{r}  = z_s)}  = \alpha ^2 {\sin ^2 \left( {\frac{{d_s \pi }}{{2m}}} \right)} .
\end{equation}

The probability of finding $\left|ax_2 \right\rangle=\left|1 \right\rangle$ after Step (2-i) in the $r^{th}$ iteration, i.e. $r>1$ is given by,

\begin{equation}
Pr^{(r)}{(ax_2  = 1)}  = \frac{{\sum\limits_{k = 0}^{M - 1} {\sin ^{2r} \left( {\frac{{d_k \pi }}{{2m}}} \right)} }}{{\sum\limits_{k = 0}^{M - 1} {\sin ^{2(r - 1)} \left( {\frac{{d_k \pi }}{{2m}}} \right)} }}.
\end{equation}

The probability of finding $\left|\psi_r \right\rangle=\left|z_s \right\rangle$ after Step (2-i) in the $r^{th}$ iteration, i.e. $r>1$ is given by,

\begin{equation}
Pr^{(r)}{(\psi_{r}  = z_s)}  = \frac{{{\sin ^{2r} \left( {\frac{{d_s \pi }}{{2m}}} \right)} }}{{\sum\limits_{k = 0}^{M - 1} {\sin ^{2(r - 1)} \left( {\frac{{d_k \pi }}{{2m}}} \right)} }}.
\end{equation}

Since the Sine function is a decreasing function then for sufficient large $r$,

\begin{equation}
\sum\limits_{k = 0,k\ne s}^{M - 1} {\sin ^{2r} \left( {\frac{{d_k \pi }}{{2m}}} \right)}  \approx \sin ^{2r} \left( {\frac{{d_{ns} \pi }}{{2m}}} \right),
\end{equation} 
\noindent
where $d_{ns}$ is the next maximum distance less than $d_s$.

The values of $d_s$ and $d_{ns}$ are unknown in advance, so let $d_s=m$ be the number of edges, 
then in the worst case when $d_s=m$, $d_{ns}=m-1$ and $m=n(n-1)/2$, the required number of iterations $r$ 
for $\epsilon  = 10^{ - \lambda }$ and $\lambda>0$ can be calculated using the formula,

\begin{equation}
0 < \sin ^{2r} \left( {\frac{{(m-1) \pi }}{{2m}}} \right) \le \epsilon,
\end{equation} 

\begin{equation}
\begin{array}{l}
 r \ge \frac{{\log \left( \epsilon  \right)}}{{2\log \left( {\sin \left( {\frac{{\left( {m - 1} \right)\pi }}{{2m}}} \right)} \right)}} \\ 
 \,\,\,\, = \frac{{\log \left( {10^{ - \lambda } } \right)}}{{2\log \left( {\cos \left( {\frac{\pi }{{2m}}} \right)} \right)}} \\ 
 \,\,\,\, \ge \lambda \left( {\frac{{2m}}{\pi }} \right)^2  \\
 \,\,\,\,=O\left( {m^2 } \right),\\
 \end{array}
\end{equation} 
\noindent
where $0 \le m \le {\textstyle{{n(n - 1)} \over 2}}$.

